                if (!okF) {
                    var tx = "";
                    try { tx = request(a1, { timeout: 20000 }); } catch (g2) { }
                    if (!tx || String(tx).length < 100) { return "toast://下载失败，检查网络后重试"; }
                    try { writeFile(fp, String(tx)); } catch (g3) { return "toast://写入失败：无存储权限？"; }
                    try { okF = fileExist(fp); } catch (g4) { }
                    if (!okF) { return "toast://写入后仍找不到文件"; }
                }
                putMyVar("acc_reset", "1");
                putMyVar("acc_py", fp);
                clearMyVar("acc_cat_id");
                clearMyVar("acc_kw");
                try { setItem("acc_last_py", fp); } catch (g5) { }
                try {
                    var rp = "";
                    try { rp = String(getPath(fp)); } catch (g6) { }
                    if (rp.indexOf("file://") === 0) { rp = rp.substring(7); }
                    var dpart = rp.replace(/[^\/]*$/, "");
                    if (dpart) {
                        var rawd = "";
                        try { rawd = getItem("acc_dirs", "") || ""; } catch (g7) { }
                        if (rawd.indexOf(dpart) < 0) {
                            try { setItem("acc_dirs", (rawd ? rawd + "\n" : "") + dpart); } catch (g8) { }
                        }
                    }
                } catch (g9) { }
                refreshPage(false);
                return "toast://已设为当前站点：" + n1 + "\n返回首页即可浏览";
            }, api, key, nm)
        });
    }
    // ===== 分页导航（替代原来失效的「加载更多」）=====
    // ★ 原实现的坑：点一次「加载更多」后 updateItem 把按钮 url 换成了 refreshPage 空壳，
    //   而 refreshPage 把 MY_PAGE 重置为 1 → isP1=true → 页码归零 → 又回到第一页。
    //   所以表现是「只能翻一页就翻不动」。现在按钮只改页码再刷新，语义一致。
    if (totalPages > 1) {
        var navRow = [];
        if (page > 0) { navRow.push({ t: "\u25C0\u4E0A\u4E00\u9875", d: -1 }); }
        navRow.push({ t: "\u2B05\u9996\u9875", d: -999 });
        if (page < totalPages - 1) { navRow.push({ t: "\u4E0B\u4E00\u9875\u25B6", d: 1 }); }
        navRow.push({ t: "\u672B\u9875\u2192", d: 999 });
        for (var vk = 0; vk < navRow.length; vk++) {
            d.push({
                title: navRow[vk].t,
                col_type: "scroll_button",
                url: $("hiker://empty#noHistory#").lazyRule(function (delta) {
                    var _p = 0;
                    try { _p = parseInt(getMyVar("acc_opage", "0")) || 0; } catch (_v1) { _p = 0; }
                    if (delta === -999) { _p = 0; }
                    else if (delta === 999) { _p = 99999; }
                    else { _p = _p + delta; }
                    if (_p < 0) { _p = 0; }
                    putMyVar("acc_opage", String(_p));
                    refreshPage(false);
                    return "hiker://empty";
                }, navRow[vk].d)
            });
        }
        d.push({
            title: "\uD83D\uDD22\u8DF3\u9875",
            col_type: "scroll_button",
            url: $("hiker://empty#noHistory#").lazyRule(function () {
                return $("1", "\u8F93\u5165\u9875\u7801").input(function () {
                    var _pp = parseInt(input) || 1;
                    if (_pp < 1) { _pp = 1; }
                    putMyVar("acc_opage", String(_pp - 1));
                    refreshPage(false);
                    return "hiker://empty";
                });
            })
        });
        d.push({
            title: "\u7B2C " + (page + 1) + " / " + totalPages + " \u9875 \u00B7 \u672C\u9875 " + (end - start) + " \u6761 \u00B7 \u5171 " + list.length + " \u7AD9",
            col_type: "text_center_1",
            url: "hiker://empty"
        });
    }
    setResult(d);
}
"}]
